197	export function endingOf(signals: TurnSignals): TurnEnding {
198	  const named = signals.directive.trim();
199	  const next = named === "" ? undefined : { agent: named };
200	
201	  if (!signals.succeeded || signals.endedBecause === "failed") return { ended: "failed" };
202	  if (signals.endedBecause === "loop") return { ended: "looped" };
203	  if (signals.endedBecause === "stopped") return { ended: "stopped" };
204	  if (signals.endedBecause === "iterations" || signals.endedBecause === "runtime") return { ended: "spent" };
205	  // A park beats the chain limits and every ordinary ending: the children it
206	  // started are already running, so the node is held no matter what the counters
207	  // say about the chain that launched them. The limits catch the re-invoked
208	  // parent instead.
209	  if (signals.parked) return { ended: "parked" };
210	  if (signals.loopLimitReached) return { ended: "chain-over", ...(next ? { next } : {}) };
211	  if (next || signals.chainContinues) return { ended: "handed-off", ...(next ? { next } : {}) };
212	  if (!signals.reported) return { ended: "no-report" };
213	  return { ended: "finished" };
214	}
215	
216	/**
217	 * Whether the at-most-one-turn-per-node guard should be released.
218	 *
219	 * Two endings hold it. `handed-off` is work actively going on THIS node, possibly
220	 * after the run that held it stopped. `parked` is work going on UNDER this node —
221	 * the run stopped inside a child-starting call, and the aggregation re-invocation
222	 * is what continues it (#208). Every other ending has handed back — to a person,
223	 * or to nobody — and a node nothing is working on must not stay locked.
224	 *
225	 * The mechanism that enacts this is the `atomaton/in-progress` label, in
226	 * `entrypoints/machinery/manage_turn_labels.ts`. It is deliberately not named
227	 * here: the rule is about turns and the label is one way to persist it.
228	 */
229	export function shouldReleaseGuard(ending: TurnEnding): boolean {
230	  return ending.ended !== "handed-off" && ending.ended !== "parked";
231	}
232	
233	/** Who to start now, when this turn handed off to somebody and the chain may continue. */
234	export function nextToDispatch(ending: TurnEnding): NextTurn | undefined {
235	  return ending.ended === "handed-off" ? ending.next : undefined;
236	}
237	
238	/**
239	 * Who this turn named, when the chain's own limit is what stops them running.
240	 *
241	 * Separate from `nextToDispatch` because the two are what a person reads the
242	 * difference between: one is a hand-off that happened, the other is a hand-off that
243	 * was refused and is now somebody's to take by hand.
244	 */
245	export function refusedByChainLimit(ending: TurnEnding): NextTurn | undefined {
246	  return ending.ended === "chain-over" ? ending.next : undefined;
247	}

