1	/**
2	 * turn-labels.ts — the two labels that say whose ball a node's turn is, moved together.
3	 *
4	 * `atomaton/in-progress` says work is in flight under the node: a run executing, or
5	 * a turn parked on agents working under it (#208). `atomaton/waiting-for-person`
6	 * says the turn came back and the machinery is waiting for a person (#223). The two
7	 * are complementary by construction, which is why one function moves both: a caller
8	 * that remembered to add one and forgot the other would leave a node wearing both
9	 * or neither, and neither state is readable.
10	 *
11	 * Best effort throughout, like every label write: the thread is the turn's record
12	 * and the labels are its cache. Every failure is a warning naming what was lost.
13	 */
14	import { gh } from "../../../adapters/github/gh.ts";
15	import { getLabel } from "../../../adapters/runner/config.ts";
16	
17	export type TurnLabelPhase =
18	  /** A run took the turn: `in-progress` on, `waiting-for-person` off. */
19	  | "running"
20	  /** The turn came back to a person: `in-progress` off, `waiting-for-person` on. */
21	  | "with-person";
22	
23	export function applyTurnLabels(phase: TurnLabelPhase, repo: string, number: string): void {
24	  const inProgress = getLabel("in_progress");
25	  const waitingForPerson = getLabel("waiting_for_person");
26	  const edit = (action: "--add-label" | "--remove-label", label: string) =>
27	    gh("issue", "edit", number, action, label, ...(repo ? ["--repo", repo] : []));
28	
29	  if (phase === "running") {
30	    // Created if missing, so a renamed label or a fresh config still lands.
31	    gh("label", "create", inProgress, "--force", "-c", "0366d6", "-d", "Issue is being worked on by an Atomaton agent");
32	    const added = edit("--add-label", inProgress);
33	    if (added.code !== 0) console.error(`::warning::could not add '${inProgress}' to #${number}`);
34	    const removed = edit("--remove-label", waitingForPerson);
35	    if (removed.code !== 0) console.error(`::warning::could not remove '${waitingForPerson}' from #${number}`);
36	    return;
37	  }
38	
39	  gh("label", "create", waitingForPerson, "--force", "-c", "fbca04", "-d", "The turn is with a person on this issue or pull request");
40	  const removed = edit("--remove-label", inProgress);
41	  if (removed.code !== 0) console.error(`::warning::could not remove '${inProgress}' from #${number}`);
42	  const added = edit("--add-label", waitingForPerson);
43	  if (added.code !== 0) console.error(`::warning::could not add '${waitingForPerson}' to #${number}`);
44	}

